#!/bin/sh
# usage: rank-presets.sh [stick.tsv] [strobe.tsv] [budget-ms] > presets.txt
# the shipped milkdrop list from viz-bench's tables (id, median_ms, p95_ms, frames, strobe, source; ids
# milkdrop:<preset>): a preset ships when its median frame on the stick is within the budget (20 ms, S5) and the
# strobe check passed, in either table (the check reads luminance, so a run on any gpu, llvmpipe included, counts).
# cheapest first
set -eu
here=$(cd "$(dirname "$0")" && pwd)
stick=${1:-$here/measurements/stick.tsv}
strobe=${2:-$here/measurements/strobe.tsv}
budget=${3:-20}
echo "# generated by rank-presets.sh: median <= $budget ms on the stick ($(basename "$stick")) and strobe ok; do not edit"
awk -F '\t' -v b="$budget" '
  FNR == 1 || $0 ~ /^#/ || $1 !~ /^milkdrop:/ { next }
  { name = substr($1, 10) }
  FILENAME == ARGV[1] { if ($5 == "ok") ok[name] = 1; next }
  { if ($5 == "ok") ok[name] = 1; ms[name] = $2 }
  END { for (n in ms) if (ms[n] + 0 <= b + 0 && ok[n]) printf "%010.3f\t%s\n", ms[n], n }
' "$strobe" "$stick" | LC_ALL=C sort | cut -f2-
